"""Aggregate artifacts without fitting or revising models after OOF evaluation."""
import sys,json,hashlib,time,platform,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
import numpy as np,pandas as pd,torch
from src.phase17_ssd.data import P,R,cfg,source,write

def table(df):
    def fmt(v):return f'{v:.6f}' if isinstance(v,(float,np.floating)) else str(v)
    return '| '+' | '.join(df.columns)+' |\n| '+' | '.join(['---']*len(df.columns))+' |\n'+'\n'.join('| '+' | '.join(fmt(v) for v in row)+' |' for row in df.itertuples(index=False,name=None))

def main():
    training=json.loads((P/'FORMAL_TRAINING_DONE.json').read_text());assert training['status']=='PASS'
    assert json.loads((R/'INDEPENDENT_VALIDATION.json').read_text())['status']=='PASS'
    histories=[];summaries=[];mechanism=[];diagnostics=[];counts={};source_hashes={}
    for stage in ['pilot','repair_inner','tuning','inner','outer','paper_pilot','paper_inner','paper_outer']:
        paths=sorted((P/stage).glob('*.pt'));counts[stage]=len(paths)
        for p in paths:
            z=torch.load(p,map_location='cpu',weights_only=False);source_hashes.setdefault(stage,set()).add(z['source'])
            if stage not in ['inner','outer','paper_inner','paper_outer']:continue
            base={'stage':stage,'arm':z['arm'],'seed':z['seed'],'fold':z['fold']}
            histories.extend([{**base,**v} for v in z['history']])
            diag={**base,'selected_epoch':z['selected_epoch'],'actual_epochs':len(z['history']),'hit_epoch_cap':len(z['history'])==cfg()['training']['max_epochs'],'first_train_loss':z['history'][0]['train_loss'],'last_train_loss':z['history'][-1]['train_loss'],'first_validation_loss':z['history'][0].get('validation_loss',np.nan),'last_validation_loss':z['history'][-1].get('validation_loss',np.nan),'first_validation_Harrell':z['history'][0].get('validation_Harrell',np.nan),'selected_validation_Harrell':z['history'][z['selected_epoch']-1].get('validation_Harrell',np.nan)}
            diagnostics.append(diag)
            sm=z['summary'];summaries.append({**base,**{k:v for k,v in sm.items() if k!='gradient_norms'},'actual_epochs':len(z['history']),'selected_epoch':z['selected_epoch']})
            if stage=='outer':mechanism.append({**base,**z['mechanism']})
    pd.DataFrame(histories).to_csv(R/'TRAINING_CURVES.csv',index=False);pd.DataFrame(diagnostics).to_csv(R/'TRAINING_DIAGNOSTICS.csv',index=False);pd.DataFrame(summaries).to_csv(R/'MODEL_CELL_SUMMARY.csv',index=False);pd.DataFrame(mechanism).to_csv(R/'MODULE_MECHANISM.csv',index=False)
    st=pd.read_csv(R/'SEED_OOF_METRICS.csv');out=st.groupby('arm',sort=False)[['Harrell','Uno60']].agg(['mean','std']);out.columns=['_'.join(v) for v in out.columns];out=out.reset_index();out.to_csv(R/'SUMMARY.csv',index=False)
    ps=pd.read_csv(R/'PFI_SEED_OOF_METRICS.csv');po=ps.groupby('arm',sort=False)[['Harrell','Uno60']].mean().reset_index();po.to_csv(R/'PFI_SUMMARY.csv',index=False)
    sm=pd.DataFrame(summaries);ms=sm[sm.stage.isin(['outer','paper_outer'])].groupby('arm').agg(outer_cells=('fold','size'),registered_parameters_min=('registered_parameters','min'),registered_parameters_max=('registered_parameters','max'),gradient_tensor_parameters_min=('last_step_gradient_parameters','min'),peak_GPU_MB_max=('peak_GPU_MB','max'),sum_training_seconds=('seconds','sum'),selected_epoch_median=('selected_epoch','median'),selected_epoch_max=('selected_epoch','max')).reset_index();ms.to_csv(R/'MODEL_SUMMARY.csv',index=False)
    ci=pd.read_csv(R/'PAIRED_COMPARISONS.csv');primary=ci[ci.family=='primary'];positive=bool((primary.Bonferroni_low>0).all())
    any_point_positive=bool((primary.delta>0).all())
    decision='INTERNAL_MECHANISM_SUPPORTED' if positive else 'EXPLORATORY_POSITIVE_ONLY' if any_point_positive else 'MECHANISM_NOT_SUPPORTED'
    cx=pd.read_csv(R/'CONTEXT_STATE_AUDIT.csv');lr=pd.read_csv(R/'LONG_RANGE_STATE_GRADIENT.csv');cp=pd.read_csv(R/'COMPUTE_ABLATION.csv');budget=pd.DataFrame(diagnostics);inner=budget[budget.stage.isin(['inner','paper_inner'])]
    summary={'status':decision,'training_source':source(),'actual_outer_neural_cells':counts['outer'],'actual_outer_paper_cells':counts['paper_outer'],'actual_outer_simple_fits':10,'actual_inner_neural_cells':counts['inner'],'actual_inner_paper_cells':counts['paper_inner'],'actual_prelock_cells':sum(counts[k] for k in ['pilot','repair_inner','tuning','paper_pilot']),'actual_inner_simple_candidate_fits':20,'actual_label_mutation_training_checks':6,'all_outer_fits':counts['outer']+counts['paper_outer']+10,'counts':counts,'formal_wall_hours':training['wall_hours'],'primary_all_corrected_lower_gt0':positive,'TransSurv':'BLOCKED;official code and multiscale features unavailable','external_confirmation':False}
    write(R/'decision.json',summary)
    ratio=lr.groupby('position_decile').gradient_fraction.mean();state_tail=float(ratio.loc[10]);selected_one=int((inner.selected_epoch==1).sum());atcap=int(inner.hit_epoch_cap.sum())
    gate_mean=float(cx.gate_valid_mean.mean());gate_std=float(cx.gate_valid_std.mean());grel=float(cx.g_matched_wrong_relative_L2.median());dt=float(cx.dt_matched_wrong_relative_L2.median());brel=float(cx.B_matched_wrong_relative_L2.median());hrel=float(cx.h_matched_wrong_relative_L2.median());risk=float(cx.matched_wrong_risk_mean_abs.median())
    lines=['# Phase17 — Conditional S6 SSD-Fusion','','## 判定','',f'**{decision}**。算子可执行且条件路径真实可导，但本队列未证实其带来可重复的条件生存排序增量。不能据此否定所有生物先验/组学融合idea，也不能将未显著解释为等效。','','## 实际执行','',f"主线165个外层cell、论文适配30个外层cell、简单Ridge10个实际外层拟合，共{summary['all_outer_fits']}。正式内层195个，加预锁定{summary['actual_prelock_cells']}个神经/论文诊断拟合；简单内层20个候选。A0/A1确定性结果在三个seed表中复用，未伪称重复独立训练。标签扰动检查另有6个两轮短训练，仅保留审计，不保存冒烟checkpoint。",'',f"正式训练队列用时{training['wall_hours']:.3f}小时；GPU为RTX4080 SUPER 32GB vGPU。逐任务峰值和设备利用率见MODEL_SUMMARY.csv、DEVICE_MONITOR.csv。",'','## DSS结果','',table(out),'','数值为每seed先按5折可比较对分子/分母求和，再取3seed均值；Uno使用IPCW加权分母。未平均跨seed风险，未把15 cells当独立队列。历史参考保留原训练协议，另列HIST；论文方法为输入/Cox适配，不是原数据原协议逐项复现。','','## 预锁定主要配对','',table(primary[['comparison','metric','delta','CI95_low','CI95_high','Bonferroni_low','Bonferroni_high']]),'','20,000次患者配对bootstrap在每个固定outer fold内独立重采样，保持折大小；相同患者计数用于所有模型和seeds。重复患者对权重count_i×count_j，IPCW由原outer-train拟合并在bootstrap冻结。四个主检验采用Bonferroni校正。二级比较全部另列且按22项家族校正。','','## 模块与失败原因','',f'- 匹配/错配的上下文g相对L2差中位数{grel:.6g}；传到Δ、B、最终状态的相对差中位数仅{dt:.6g}、{brel:.6g}、{hrel:.6g}；最终风险平均绝对差中位数{risk:.6g}。这表明上下文能改变，但条件转移的实际幅度很小。',f'- 有效patch上的门均值{gate_mean:.6f}、患者内门标准差平均{gate_std:.6g}，接近0.9初值；非塌陷到0/1，但缺少显著的患者/区域选择变化。A8−A7未通过校正检验，不能声称显式门有独立增量。',f'- 对最终递归状态平方范数求梯度，最后10% patch的梯度质量均值为{state_tail:.6f}（15个label-blind训练WSI，各checkpoint一个）。这只诊断最终状态的空间序列近因偏置，不是生物时间或医学区域真值。', '- A5/A6/A7条件Δ/B在数学上确实启用；分支置零、输入梯度、正/错配状态差详见MODULE_INTERVENTIONS.csv。没有把直接RNA风险头梯度冒充条件SSM梯度。', '- A2/A3/A4/A5/A6/A7/A8共用相同母干、patch与初始化；A4使用1664参数的rank8 FiLM，与Δ+B适配器相同。母干注册包含未启用模块，所以注册量、得到梯度的张量量均单独报告；不能宣称实际有效容量完全相等。','- A9/A10只移除或错配状态条件中的个体组学，直接与末端组学主效应仍是患者自身。A10的从头错条件训练与冻结模型推理置换分别报告。', '- 临床信息是最明显的有效组成部分：no_Clinical显著降低点估计。C-index增量不能仅按这一消融做因果归因；S32、病理和RNA的实际贡献必须同时参考条件比较与置零。','- A8未同时超过同协议Clinical+S32和历史CS+S32+CONCH32；即使超过某些较弱论文适配或全拼接Ridge点估计，也不成立SOTA声明。','','## 训练预算与修复','',f'正式195个内层模型，{selected_one}个选中epoch1，{atcap}个实际跑到160上限。所有内层最多160，连续40轮验证EMA无改善才停止；外层精确重训选中epoch，学习率schedule一致。首轮22个诊断模型全部训练160轮且最优在1–6；训练继续下降而验证恶化支持过拟合诊断。不能把早选epoch等同于事件数量是唯一瓶颈，或宣称任意更长预算必无收益。','','1. 修复minimum_epoch16排除早期最优的问题：两折A8实际重跑，曲线一致，选中epoch变为1/6；旧/新表在INNER_SELECTION_REPAIR.csv。','2. 按内层对比选择共同dropout0.25/weight_decay0.01；验证损失差很小，不把这一步宣称为机制创新。','3. 纠正FiLM容量与padding统计，正式前已完成。未在看到outer指标后扩模型、换loss或增加第二条结构修复。','4. 自动确定性扫描兼容、错条件仅更换状态上下文等实现问题见BUG_LOG.csv。评测阶段新增历史OOF容差1e-9，仅处理float64点积机器精度误差，不改变任何训练或风险排序。','','## 论文基线与可比性','', '- MGCT：固定官方提交，保留双向注意力、SNN、两阶段融合；6组签名适配为8个已核实组、输入维数1536及RNA/CNA+mask，分类头改1维Cox风险，并统一临床/S32锚点及直接组学捷径。官方第一stage2块不接入最终结果的行为保持；注册参数不等于有梯度参数。批量端口与原层B=1输出/梯度逐元素一致。','- MambaMIL：固定官方SRMamba和MIL实现，保留序列重排、两层512维、attention pooling；更换1维Cox头，加统一Clinical/S32及直接组学late adapter。官方旧fast helper用兼容版本官方causal_conv1d+selective_scan替代；原Euler输入离散化与门控D skip保留，非本方法exact-ZOH。逐N输出/梯度与字面递推核验通过。','- 原生输入与适配输入分开记载；MGCT/MambaMIL容量明显大于约d64的本方法，不能当参数完全匹配比较。','- TransSurv：未取得可核验官方实现且缺多尺度WSI输入，BLOCKED；没有挂名替代或填入文献C-index。ME-Mamba/CAMR/MMP来源核查见LITERATURE_BASELINES.md。这意味着prompt的三种正式论文方法最低目标尚未全部满足。','','## PFI冻结迁移敏感性','',table(po),'','PFI510人/129事件，仅使用对应DSS冻结风险，无PFI训练/超参选择。PFI与DSS终点含义不同，不能把其差异直接归因于DSS事件数。','','## 证据边界与下一步','','优势：真实可导的条件转移、完整对照、逐checkpoint重放、训练折内处理和独立配对统计均可审计。','','风险：本cohort65DSS事件、反复开发、candidate-pool-limited/geometry-only-validation、无原始组织学QA；没有独立外部验证。置信度：本轮不支持预锁定H1的结论为高；“条件效应微小/门接近初值”数值诊断为高；造成这些现象的唯一生物/统计原因置信度低。','','后续优先检验如何让训练保留临床锚点并获得非微小的有效条件状态变化，必须作为新的探索性协议，先用内层和无标签诊断；不能在本轮外折上继续修复救榜。若要满足全部论文基线目标，需要可核验TransSurv作者代码及对应多尺度资产。']
    (R/'RESULTS.md').write_text('\n'.join(lines)+'\n',encoding='utf8')
    (R/'DECISION.md').write_text(f'# Decision\n\n**{decision}**\n\nA8−A3和A8−A7四项主要检验均未取得校正CI下界大于0的证据。冻结协议实际完成，TransSurv官方复现仍阻塞。算子路径真实存在不等于患者特异性机制有效；不能否定所有组学融合idea。\n',encoding='utf8')
    write(R/'EXECUTION_COUNTS.json',{**summary,'stage_source_hashes':{k:sorted(v) for k,v in source_hashes.items()},'secondary_PFI_new_fits':0,'new_inner_optimizer_fits_total':counts['inner']+counts['paper_inner']+summary['actual_prelock_cells']+20,'new_neural_short_label_mutation_checks':6})
    print(out.to_string(index=False),flush=True);print(json.dumps(summary),flush=True)

if __name__=='__main__':main()
